import sympy as sp

# Define the function to check if a number is prime
def is_prime(n):
    return sp.isprime(n)

# Function to find the smallest prime that is the sum of two distinct primes
def find_smallest_prime_sum():
    for p1 in range(2, 1000):
        for p2 in range(2, 1000):
            if p1 != p2 and is_prime(p1 + p2):
                return p1 + p2

# Find and print the smallest prime that is the sum of two distinct primes
smallest_prime_sum = find_smallest_prime_sum()
print(smallest_prime_sum)

